// ─────────────────────────────────────────────────────────────────────────────
// utils/sound.js  — Web Audio API sound effects, respects settings
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Play a sound effect.
 * @param {"add"|"remove"|"scan"|"error"} type
 * @param {object} snd  — subset of settings (soundEnabled, soundVolume, soundOnXxx)
 */
export function playSound(type, snd = {}) {
  if (snd.soundEnabled === false) return;
  const typeKey = type === "add"    ? "soundOnAdd"
                : type === "remove" ? "soundOnRemove"
                : type === "scan"   ? "soundOnScan"
                :                     "soundOnError";
  if (snd[typeKey] === false) return;

  const vol = ((snd.soundVolume ?? 70) / 100) * 0.3;

  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const g   = ctx.createGain();
    g.connect(ctx.destination);

    if (type === "add") {
      [0, 0.12].forEach((t, i) => {
        const o  = ctx.createOscillator(); o.type = "sine";
        o.frequency.setValueAtTime(520 + i*180, ctx.currentTime + t);
        o.frequency.exponentialRampToValueAtTime(700 + i*180, ctx.currentTime + t + 0.1);
        const gn = ctx.createGain();
        gn.gain.setValueAtTime(vol, ctx.currentTime + t);
        gn.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + 0.18);
        o.connect(gn); gn.connect(ctx.destination);
        o.start(ctx.currentTime + t); o.stop(ctx.currentTime + t + 0.18);
      });
    } else if (type === "remove") {
      const o = ctx.createOscillator(); o.type = "sine";
      o.frequency.setValueAtTime(440, ctx.currentTime);
      o.frequency.exponentialRampToValueAtTime(220, ctx.currentTime + 0.22);
      g.gain.setValueAtTime(vol, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
      o.connect(g); o.start(); o.stop(ctx.currentTime + 0.25);
    } else if (type === "error") {
      const o = ctx.createOscillator(); o.type = "square";
      o.frequency.setValueAtTime(160, ctx.currentTime);
      g.gain.setValueAtTime(vol * 0.5, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.18);
      o.connect(g); o.start(); o.stop(ctx.currentTime + 0.18);
    } else if (type === "scan") {
      const o = ctx.createOscillator(); o.type = "sine";
      o.frequency.setValueAtTime(900, ctx.currentTime);
      g.gain.setValueAtTime(vol * 0.8, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
      o.connect(g); o.start(); o.stop(ctx.currentTime + 0.1);
    }
  } catch {}
}
