// components/Toggle.js
export function Toggle({ on, onToggle }) {
  return (
    <button onClick={onToggle}
      style={{width:44,height:26,borderRadius:13,border:"none",cursor:"pointer",
        transition:"background 0.2s",background:on?"var(--green)":"var(--surface3)",
        position:"relative",flexShrink:0}}>
      <span style={{position:"absolute",top:3,width:20,height:20,borderRadius:10,
        background:"#fff",transition:"left 0.2s",left:on?"21px":"3px",display:"block"}}/>
    </button>
  );
}
