// components/ConfirmModal.js
import { Mo } from "../utils/theme";

export function ConfirmModal({ icon="⚠️", title, message, confirmLabel="Confirm",
  confirmColor="var(--red)", onConfirm, onCancel }) {
  return (
    <div style={Mo.overlay}>
      <div style={{...Mo.modal,maxWidth:320,textAlign:"center"}}>
        <div style={{fontSize:44,marginBottom:10}}>{icon}</div>
        <div style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800,marginBottom:8}}>
          {title}
        </div>
        <p style={{fontSize:13,color:"var(--text-mid)",marginBottom:22,lineHeight:1.6}}>
          {message}
        </p>
        <div style={{display:"flex",gap:10,justifyContent:"center"}}>
          <button onClick={onCancel} style={Mo.cancelBtn}>Cancel</button>
          <button onClick={onConfirm}
            style={{...Mo.confirmBtn,background:confirmColor}}>
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}
