// components/ImportModal.js
import { useState, useRef } from "react";
import { Mo, SS } from "../utils/theme";
import { csvToItems } from "../utils/csv";

export function ImportModal({ onImport, onClose }) {
  const [text,    setText]    = useState("");
  const [mode,    setMode]    = useState("merge");
  const [preview, setPreview] = useState(null);
  const [err,     setErr]     = useState("");
  const fileRef = useRef(null);

  function handleFile(e) {
    const f = e.target.files[0]; if (!f) return;
    const r = new FileReader();
    r.onload = ev => { setText(ev.target.result); setPreview(null); setErr(""); };
    r.readAsText(f);
  }

  function handlePreview() {
    try { setPreview(csvToItems(text)); setErr(""); }
    catch (e) { setErr("Invalid CSV: " + e.message); }
  }

  return (
    <div style={Mo.overlay}>
      <div style={Mo.modal}>
        <div style={Mo.header}>
          <span style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800}}>
            ⬆ Import CSV
          </span>
          <button onClick={onClose} style={Mo.xBtn}>✕</button>
        </div>
        <p style={{fontSize:12,color:"var(--text-mid)",marginBottom:12}}>
          Import a CSV file previously exported from this app.
        </p>
        <input ref={fileRef} type="file" accept=".csv,text/csv"
          onChange={handleFile} style={{display:"none"}}/>
        <button onClick={()=>fileRef.current?.click()}
          style={{...SS.secondaryBtn,marginBottom:10,fontSize:12}}>
          📂 Choose CSV file
        </button>
        {text    && <div style={{fontSize:11,color:"var(--green)",marginBottom:10}}>
          ✓ File loaded ({text.split("\n").length-1} rows)</div>}
        {err     && <div style={{fontSize:11,color:"var(--red)",marginBottom:10}}>{err}</div>}
        {preview && <div style={{fontSize:12,color:"var(--green)",background:"var(--green-bg)",
          padding:8,borderRadius:6,marginBottom:10}}>
          Preview: {preview.length} items found</div>}
        <div style={{display:"flex",gap:8,marginBottom:14}}>
          {["merge","replace"].map(m=>(
            <button key={m} onClick={()=>setMode(m)}
              style={{flex:1,padding:"8px",borderRadius:8,cursor:"pointer",
                border:`1px solid ${mode===m?"var(--green)":"var(--border)"}`,
                background:mode===m?"var(--green-bg)":"transparent",
                color:mode===m?"var(--green)":"var(--text-mid)",
                fontFamily:"DM Mono,monospace",fontSize:12}}>
              {m==="merge"?"Merge (keep existing)":"Replace all"}
            </button>
          ))}
        </div>
        <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
          <button onClick={onClose} style={Mo.cancelBtn}>Cancel</button>
          {!preview
            ? <button onClick={handlePreview} disabled={!text}
                style={{...SS.primaryBtn,opacity:text?1:0.4}}>Preview</button>
            : <button onClick={()=>onImport(preview,mode)} style={SS.primaryBtn}>
                Import {preview.length} items
              </button>}
        </div>
      </div>
    </div>
  );
}
