export const uid = () => Math.random().toString(36).slice(2, 10);

// ─────────────────────────────────────────────────────────────────────────────
// inferCategory — maps OpenFoodFacts tags or a free-text name to one of our
// categories. Pass either:
//   • an array of OFF tags (categories_tags from the API), OR
//   • a plain string (item name for the quick-add fallback)
// Returns one of our CATEGORIES strings, defaulting to "Other".
// ─────────────────────────────────────────────────────────────────────────────
const CAT_RULES = [
  // Each entry: [category, [...keywords that appear in the tag/name]]
  // Ordered most-specific first so ambiguous tags resolve correctly.
  ["Dairy",               ["milk","dairy","cheese","yogurt","yoghurt","cream","butter","fromage","lait","quark","kefir","whey"]],
  ["Meat & Fish",         ["meat","beef","pork","chicken","poultry","turkey","lamb","veal","fish","seafood","salmon","tuna","shrimp","prawn","sausage","bacon","ham","deli"]],
  ["Fruits & Vegetables", ["fruit","vegetable","produce","salad","greens","berry","berries","apple","banana","orange","tomato","potato","onion","garlic","carrot","lettuce","spinach","broccoli","avocado","mushroom","herb","fresh"]],
  ["Grains & Pasta",      ["pasta","noodle","rice","grain","cereal","oat","flour","bread mix","couscous","quinoa","barley","wheat","corn","tortilla","cracker","starch"]],
  ["Canned Goods",        ["canned","tinned","can ","conserve","preserved","jar ","legume","bean","lentil","chickpea","pea","soup","broth","stock","tomato sauce","passata"]],
  ["Snacks",              ["snack","chip","crisp","popcorn","pretzel","candy","chocolate","sweet","biscuit","cookie","wafer","nut","seed","trail mix","bar ","energy bar","granola bar"]],
  ["Beverages",           ["beverage","drink","juice","water","soda","cola","tea","coffee","beer","wine","spirit","alcohol","smoothie","milk drink","syrup","squash","lemonade","kombucha"]],
  ["Condiments",          ["condiment","sauce","ketchup","mustard","mayonnaise","vinegar","dressing","marinade","spice","seasoning","herb ","salt","pepper","oil","olive oil","relish","chutney","jam","jelly","honey","syrup ","spread","paste","pesto"]],
  ["Frozen",              ["frozen","freeze","ice cream","gelato","sorbet"]],
  ["Bakery",              ["bread","bakery","pastry","cake","muffin","bagel","croissant","bun","roll","donut","waffle","pancake","pie","tart","loaf"]],
  ["Toiletries",          ["toiletry","shampoo","conditioner","soap","body wash","deodorant","toothpaste","toothbrush","razor","hygiene","shower","lotion","moisturiser","moisturizer","sunscreen","perfume","cologne","feminine","tampon","pad ","dental","mouthwash","hair","skin care","skincare","face wash","lip"]],
  ["Medicine",            ["medicine","medication","vitamin","supplement","tablet","capsule","pill","pain relief","painkiller","antibiotic","pharmacy","drug","remedy","allergy","cough","cold ","flu","first aid","bandage","antiseptic","ibuprofen","paracetamol","aspirin","probiotic"]],
  ["Cleaning",            ["cleaning","cleaner","detergent","bleach","disinfectant","laundry","dishwash","soap powder","fabric softener","wipe","mop","sponge","polish","toilet","bathroom","floor cleaner","spray "]],
];

/**
 * @param {string[]|string} input — OFF categories_tags array, or a plain name string
 * @returns {string} one of our CATEGORIES values
 */
export function inferCategory(input) {
  // Normalise to an array of lowercase strings to search through
  const haystack = Array.isArray(input)
    ? input.map(t => t.replace(/^[a-z]{2}:/, "").replace(/-/g, " ").toLowerCase())
    : [String(input).toLowerCase()];

  for (const [cat, keywords] of CAT_RULES) {
    for (const hay of haystack) {
      if (keywords.some(kw => hay.includes(kw))) return cat;
    }
  }
  return "Other";
}

export const mkHistory = (type, qty, note = "", by = "") => ({
  id: uid(), type, qty, note, by, at: new Date().toISOString(),
});

/**
 * Stock level descriptor.
 * @param {number} qty
 * @param {number} lowAt  — "running low" threshold from settings
 */
export function stockLvl(qty, lowAt = 2) {
  if (qty <= 0)          return { label:"Out of stock", color:"#e63312", bar:0 };
  if (qty === 1)         return { label:"Last one",     color:"#e77d00", bar:15 };
  if (qty <= lowAt)      return { label:"Running low",  color:"#f7c800", bar:35 };
  if (qty <= lowAt * 2)  return { label:"Moderate",     color:"#85bb2f", bar:65 };
  return                        { label:"Well stocked", color:"#4caf7d", bar:100 };
}

// ─────────────────────────────────────────────────────────────────────────────
// CRDT quantity helpers — PN-Counter per device
//
// Structure per item:
//   kitchenBase / storageBase  — agreed baseline set at item creation
//   kitchenP[deviceId]  — cumulative units *added*   to kitchen by that device
//   kitchenN[deviceId]  — cumulative units *removed* from kitchen by that device
//   storageP / storageN — same for storage
//
// kitchenQty = kitchenBase + Σ(kitchenP) - Σ(kitchenN)  (clamped ≥ 0)
//
// Merge rule: for each deviceId take max(local, remote) on both P and N.
// This is commutative, associative, and idempotent — order never matters.
// ─────────────────────────────────────────────────────────────────────────────

/** Sum all values in a counter map. */
function sumVec(vec) {
  return Object.values(vec || {}).reduce((a, b) => a + b, 0);
}

/** Compute actual qty from base + PN vectors, clamped to 0. */
export function computeQty(base, P, N) {
  return Math.max(0, (base || 0) + sumVec(P) - sumVec(N));
}

/** Merge two counter maps by taking the max per deviceId. */
function mergeVec(a, b) {
  const result = { ...(a || {}) };
  for (const [k, v] of Object.entries(b || {}))
    result[k] = Math.max(result[k] || 0, v);
  return result;
}

/**
 * Ensure an item has the CRDT vector fields.
 * Old items without them are migrated: current qty becomes the base.
 */
export function ensureVectors(item) {
  if (item.kitchenBase != null) return item;
  return {
    ...item,
    kitchenBase: item.kitchenQty ?? 0,
    storageBase:  item.storageQty  ?? 0,
    kitchenP: {}, kitchenN: {},
    storageP: {}, storageN: {},
  };
}

/**
 * Apply a quantity delta (positive = add, negative = remove) for a given
 * device.  Returns a new item object with updated vectors and recomputed qty.
 *
 * @param {object} item       — current item (must have CRDT vectors)
 * @param {string} deviceId
 * @param {number} kitchenDelta — change to apply to kitchenQty
 * @param {number} storageDelta — change to apply to storageQty
 */
export function applyDelta(item, deviceId, kitchenDelta, storageDelta) {
  const it = ensureVectors(item);
  const kP = { ...it.kitchenP };
  const kN = { ...it.kitchenN };
  const sP = { ...it.storageP };
  const sN = { ...it.storageN };

  if (kitchenDelta > 0) kP[deviceId] = (kP[deviceId] || 0) + kitchenDelta;
  if (kitchenDelta < 0) kN[deviceId] = (kN[deviceId] || 0) - kitchenDelta;
  if (storageDelta > 0) sP[deviceId] = (sP[deviceId] || 0) + storageDelta;
  if (storageDelta < 0) sN[deviceId] = (sN[deviceId] || 0) - storageDelta;

  return {
    ...it,
    kitchenP: kP, kitchenN: kN,
    storageP: sP, storageN: sN,
    kitchenQty: computeQty(it.kitchenBase, kP, kN),
    storageQty:  computeQty(it.storageBase,  sP, sN),
    updatedAt: Date.now(),
  };
}

/** Union two history arrays by entry id, sorted chronologically. */
function mergeHistory(a, b) {
  const map = new Map();
  for (const e of (a || [])) map.set(e.id, e);
  for (const e of (b || [])) if (!map.has(e.id)) map.set(e.id, e);
  return Array.from(map.values()).sort((x, y) => (x.at < y.at ? -1 : 1));
}

/**
 * Merge two item arrays using CRDT semantics.
 *
 * Quantities:  PN-Counter merge (order-independent, conflict-free).
 * Metadata:    last updatedAt wins per item (name, brand, category, …).
 * Deletions:   tombstone (deletedAt) propagates; pruned after 30 days.
 * History:     unioned by entry id.
 */
export function mergeItems(local, remote) {
  const map = new Map();
  for (const raw of local)  map.set(raw.id, ensureVectors(raw));
  for (const raw of remote) {
    const rem = ensureVectors(raw);
    const loc = map.get(rem.id);
    if (!loc) { map.set(rem.id, rem); continue; }

    // Merge PN vectors — commutative, takes max per device entry
    const kitchenP = mergeVec(loc.kitchenP, rem.kitchenP);
    const kitchenN = mergeVec(loc.kitchenN, rem.kitchenN);
    const storageP  = mergeVec(loc.storageP,  rem.storageP);
    const storageN  = mergeVec(loc.storageN,  rem.storageN);

    // Bases must agree — use whichever side is older (the original creator)
    const kitchenBase = loc.kitchenBase ?? rem.kitchenBase ?? 0;
    const storageBase  = loc.storageBase  ?? rem.storageBase  ?? 0;

    const kitchenQty = computeQty(kitchenBase, kitchenP, kitchenN);
    const storageQty  = computeQty(storageBase,  storageP,  storageN);

    // Metadata: newer updatedAt wins
    const locTs = loc.updatedAt || 0;
    const remTs = rem.updatedAt || 0;
    const meta = locTs >= remTs ? loc : rem;

    // Tombstone: if either side deleted, propagate it
    const deletedAt = loc.deletedAt || rem.deletedAt
      ? Math.max(loc.deletedAt || 0, rem.deletedAt || 0)
      : undefined;

    map.set(rem.id, {
      ...meta,
      kitchenBase, storageBase,
      kitchenP, kitchenN,
      storageP, storageN,
      kitchenQty, storageQty,
      history: mergeHistory(loc.history, rem.history),
      ...(deletedAt ? { deletedAt } : {}),
    });
  }

  const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
  return Array.from(map.values()).filter(i => !(i.deletedAt && i.deletedAt < cutoff));
}

/** Per-item threshold helpers — fall back to global settings. */
export const itemKitchenThreshold = (item, settings) =>
  item.kitchenThreshold ?? settings.kitchenThreshold;

export const itemTotalThreshold = (item, settings) =>
  item.totalThreshold ?? settings.totalThreshold;

export const itemExpiryWarn = (item, settings) =>
  item.expiryWarnDays ?? settings.expiryWarnDays;
