// ─────────────────────────────────────────────────────────────────────────────
// utils/sync.js  — JSONBin.io API wrappers + push/pull helpers
// ─────────────────────────────────────────────────────────────────────────────
import { JSONBIN_KEY, JSONBIN_BASE } from "../constants";
import { encryptData, decryptData }  from "./crypto";

// ── Low-level JSONBin requests ───────────────────────────────────────────────
export async function jbGet(binId) {
  const r = await fetch(`${JSONBIN_BASE}/b/${binId}/latest`, {
    headers: { "X-Master-Key": JSONBIN_KEY, "X-Bin-Meta": "false" },
  });
  return r.ok ? r.json() : null;
}

export async function jbCreate(data) {
  const r = await fetch(`${JSONBIN_BASE}/b`, {
    method:  "POST",
    headers: { "Content-Type":"application/json", "X-Master-Key":JSONBIN_KEY, "X-Bin-Private":"false" },
    body:    JSON.stringify(data),
  });
  if (!r.ok) return null;
  const j = await r.json();
  return j.metadata?.id || null;
}

export async function jbUpdate(binId, data) {
  const r = await fetch(`${JSONBIN_BASE}/b/${binId}`, {
    method:  "PUT",
    headers: { "Content-Type":"application/json", "X-Master-Key":JSONBIN_KEY },
    body:    JSON.stringify(data),
  });
  return r.ok;
}

// ── Per-code bin ID cache in localStorage ────────────────────────────────────
export function getLocalBinId(code) {
  try { return JSON.parse(localStorage.getItem(`pantry-bin-${code}`) || "null"); }
  catch { return null; }
}
export function setLocalBinId(code, binId) {
  try { localStorage.setItem(`pantry-bin-${code}`, JSON.stringify(binId)); } catch {}
}

// ── Shared pantry push / pull ────────────────────────────────────────────────
export async function pushShared(fullCode, password, items, groceryOv, transferOv, myName) {
  if (!fullCode || !password) return;
  try {
    const colonIdx  = fullCode.indexOf(":");
    const shortCode = (colonIdx >= 0 ? fullCode.slice(0, colonIdx) : fullCode).toUpperCase();
    const binId     = colonIdx >= 0 ? fullCode.slice(colonIdx + 1) : null;
    if (!binId) return;
    const enc     = await encryptData(
      { items, groceryOv, transferOv, updatedAt:Date.now(), updatedBy:myName||"Someone" },
      password + shortCode
    );
    await jbUpdate(binId, { enc, code:shortCode, updatedAt:Date.now() });
  } catch (e) { console.error("pushShared", e); }
}

export async function pullShared(fullCode, password, sinceTs = 0) {
  if (!fullCode || !password) return null;
  try {
    const colonIdx  = fullCode.indexOf(":");
    const shortCode = (colonIdx >= 0 ? fullCode.slice(0, colonIdx) : fullCode).toUpperCase();
    const binId     = colonIdx >= 0 ? fullCode.slice(colonIdx + 1) : null;
    if (!binId) return null;
    const data = await jbGet(binId);
    if (!data?.enc) return null;
    // The outer `updatedAt` is stored in plaintext — skip decryption when
    // the remote hasn't changed since our last sync (saves CPU + avoids unnecessary state).
    if (sinceTs > 0 && data.updatedAt && data.updatedAt <= sinceTs) return null;
    return await decryptData(data.enc, password + shortCode);
  } catch { return null; }
}

export function genCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length:6 }, () => chars[Math.floor(Math.random()*chars.length)]).join("");
}
