// components/LockScreen.js
import { useState } from "react";
import { APP_PASSWORD } from "../constants";
import { createSession } from "../utils/auth";

export function LockScreen({ onUnlock }) {
  const [pw, setPw]     = useState("");
  const [err, setErr]   = useState(false);
  const [shake, setShk] = useState(false);

  function attempt() {
    if (pw === APP_PASSWORD) { createSession(); onUnlock(); }
    else {
      setErr(true); setShk(true); setPw("");
      setTimeout(() => setShk(false), 500);
    }
  }

  return (
    <div style={{minHeight:"100vh",background:"var(--bg,#0f0f0c)",display:"flex",
      alignItems:"center",justifyContent:"center",padding:20}}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@800&family=DM+Mono:wght@400;500&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}body{background:var(--bg,#0f0f0c);}
        @keyframes shake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}
        @keyframes lockIn{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
      `}</style>
      <div style={{width:"100%",maxWidth:320,animation:"lockIn 0.4s ease"}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <div style={{fontSize:52,marginBottom:12}}>🥫</div>
          <div style={{fontFamily:"Fraunces,serif",fontSize:28,fontWeight:800,
            color:"var(--accent,#f5c842)"}}>Pantry</div>
          <div style={{fontSize:12,color:"var(--text-dim,#5a5848)",marginTop:4,
            fontFamily:"DM Mono,monospace"}}>Enter password to unlock</div>
        </div>
        <div style={{animation:shake?"shake 0.4s ease":undefined}}>
          <input
            type="password" value={pw} placeholder="Password"
            onChange={e=>{setPw(e.target.value);setErr(false);}}
            onKeyDown={e=>e.key==="Enter"&&attempt()}
            autoFocus
            style={{width:"100%",background:"var(--surface,#17170f)",
              border:`1px solid ${err?"var(--red,#e55a42)":"var(--border,#2e2e22)"}`,
              borderRadius:12,color:"var(--text,#e8e4d0)",padding:"14px 18px",
              fontSize:16,outline:"none",fontFamily:"DM Mono,monospace",
              textAlign:"center",letterSpacing:3,marginBottom:12}}/>
          {err&&<div style={{textAlign:"center",fontSize:12,
            color:"var(--red,#e55a42)",marginBottom:10}}>Wrong password</div>}
          <button onClick={attempt} style={{width:"100%",padding:"13px",
            background:"var(--accent,#f5c842)",color:"#0f0f0c",border:"none",
            borderRadius:12,fontFamily:"DM Mono,monospace",fontSize:14,
            fontWeight:700,cursor:"pointer"}}>
            Unlock
          </button>
        </div>
      </div>
    </div>
  );
}
