// ─────────────────────────────────────────────────────────────────────────────
// hooks/useBarcodeScanner.js
// Wraps the native BarcodeDetector API with scan-cooldown and sound support.
// ─────────────────────────────────────────────────────────────────────────────
import { useEffect, useRef } from "react";
import { playSound } from "../utils/sound";

/**
 * @param {Function} onDetected  — called with the raw barcode string
 * @param {boolean}  active      — start/stop the scanner
 * @param {React.MutableRefObject} sndOptsRef — ref to current settings object
 */
export function useBarcodeScanner(onDetected, active, sndOptsRef) {
  const vRef    = useRef(null);
  const stRef   = useRef(null);
  const rafRef  = useRef(null);
  const detRef  = useRef(null);
  const lastRef = useRef(null);
  const coolRef = useRef(false);

  useEffect(() => {
    if (!active) return;
    let cancelled = false;

    async function start() {
      if (!("BarcodeDetector" in window)) return;
      try {
        detRef.current = new window.BarcodeDetector({
          formats: ["ean_13","ean_8","upc_a","upc_e","code_128","code_39","qr_code"],
        });
        const facing = sndOptsRef?.current?.scanCamera || "environment";
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: facing,
            width:     { ideal: 1920 },
            height:    { ideal: 1080 },
            frameRate: { ideal: 60, min: 30 },
          },
        });
        if (cancelled) { stream.getTracks().forEach(t => t.stop()); return; }
        stRef.current = stream;
        if (vRef.current) { vRef.current.srcObject = stream; await vRef.current.play(); }
        scan();
      } catch (e) { console.error(e); }
    }

    async function scan() {
      if (cancelled || !vRef.current || !detRef.current) return;
      try {
        const codes = await detRef.current.detect(vRef.current);
        if (codes.length > 0 && !coolRef.current) {
          const code = codes[0].rawValue;
          if (code !== lastRef.current) {
            const snd      = sndOptsRef?.current || {};
            const cooldown = snd.scanCooldown ?? 1000;
            lastRef.current  = code;
            coolRef.current  = true;
            playSound("scan", snd);
            onDetected(code);
            setTimeout(() => { coolRef.current = false; lastRef.current = null; }, cooldown);
          }
        }
      } catch {}
      rafRef.current = requestAnimationFrame(scan);
    }

    start();

    return () => {
      cancelled = true;
      cancelAnimationFrame(rafRef.current);
      if (stRef.current) stRef.current.getTracks().forEach(t => t.stop());
    };
  }, [active, onDetected, sndOptsRef]);

  return vRef;  // attach to <video ref={vRef} />
}
