// ─────────────────────────────────────────────────────────────────────────────
// context/AppContext.js
//
// Single shared context following React's "Lifting State Up" principle.
// All features read/write through usePantry() instead of prop-drilling.
// ─────────────────────────────────────────────────────────────────────────────
import { createContext, useContext, useState, useEffect, useRef, useCallback } from "react";
import { K, DEFAULT_SETTINGS, JSONBIN_KEY } from "../constants";
import { ld, sv }                            from "../utils/storage";
import { pushShared, pullShared, jbCreate, genCode } from "../utils/sync";
import { mkHistory, uid, mergeItems } from "../utils/items";
import { playSound }                         from "../utils/sound";

const PantryContext = createContext(null);

/** Hook — consume the pantry context anywhere in the tree. */
export function usePantry() {
  const ctx = useContext(PantryContext);
  if (!ctx) throw new Error("usePantry must be used inside PantryProvider");
  return ctx;
}

export function PantryProvider({ children, onLock }) {
  // ── Device identity — stable across sessions, unique per browser/device ──────
  const deviceId = useRef((() => {
    let id = ld("pantry-device-id", null);
    if (!id) { id = uid(); sv("pantry-device-id", id); }
    return id;
  })()).current;

  // ── Persisted state ─────────────────────────────────────────────────────────
  const [items,     setItemsRaw] = useState(() => ld(K.items,    []));
  const [settings,  setSettings] = useState(() => ({ ...DEFAULT_SETTINGS, ...ld(K.settings, {}) }));
  const [groceryOv,  setGroceryOv]  = useState(() => ld(K.groceryOv,  {}));
  const [transferOv, setTransferOv] = useState(() => ld(K.transferOv, {}));

  // ── Shared pantry ───────────────────────────────────────────────────────────
  const [pantryCode,  setPantryCode]  = useState(() => ld(K.pantryCode,  null));
  const [sharePw,     setSharePw]     = useState(() => ld(K.sharePwRaw,  ""));
  const [myName,      setMyName]      = useState(() => ld(K.myName,      ""));
  const [syncStatus,  setSyncStatus]  = useState("idle");
  const [lastSyncTime,setLastSyncTime]= useState(null);
  const [lastSyncBy,  setLastSyncBy]  = useState(null);

  // ── UI state ────────────────────────────────────────────────────────────────
  const [tab,         setTabRaw]      = useState("pantry");
  const [prevTab,     setPrevTab]     = useState("pantry");
  const [mode,        setMode]        = useState("pantry");
  const [editItem,    setEditItem]    = useState(null);
  const [pantryView,  setPantryViewRaw] = useState(() => ld("pantry-view-pref", null) || settings.defaultPantryView || "compact");
  const [sortBy,      setSortByRaw]   = useState(() => ld("pantry-sort-pref", null) || settings.defaultSortBy || "name");
  const [filterCat,   setFilterCat]   = useState("All");
  const [search,      setSearch]      = useState("");
  const [toast,       setToast]       = useState(null);
  const [pendingConfirm, setPendingConfirm] = useState(null);
  const [historyItem, setHistoryItem] = useState(null);
  const [undoStack,   setUndoStack]   = useState([]);
  const [showUndoHistory, setShowUndoHistory] = useState(false);
  const [showSettingsSaved, setShowSettingsSaved] = useState(false);
  const [showGroceryExport, setShowGroceryExport] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showAddSheet, setShowAddSheet] = useState(false);
  const [showQR,       setShowQR]     = useState(false);
  const [scanning,    setScanning]    = useState(false);
  const [scanStatus,  setScanStatus]  = useState("idle");
  const [scanLocation,setScanLocation]= useState("kitchen");
  const [scanCard,    setScanCard]    = useState(null);
  const [pendingRm,   setPendingRm]   = useState([]);
  const [showRmReview,setShowRmReview]= useState(false);
  // Shared pantry creation state
  const [createPw,  setCreatePw]  = useState("");
  const [createPw2, setCreatePw2] = useState("");
  const [createPwErr,setCreatePwErr] = useState("");
  const [joinCode,  setJoinCode]  = useState("");
  const [joinPw,    setJoinPw]    = useState("");
  const [joinErr,   setJoinErr]   = useState("");

  const savedSettingsRef = useRef(JSON.stringify(settings));

  // ── Persistence side-effects ─────────────────────────────────────────────
  function setItems(fn) {
    setItemsRaw(prev => {
      const next = typeof fn === "function" ? fn(prev) : fn;
      sv(K.items, next); return next;
    });
  }
  useEffect(() => { sv(K.settings,  settings);   }, [settings]);
  useEffect(() => { sv(K.groceryOv,  groceryOv);  }, [groceryOv]);
  useEffect(() => { sv(K.transferOv, transferOv); }, [transferOv]);
  useEffect(() => { sv(K.myName,    myName);      }, [myName]);
  useEffect(() => { sv("pantry-view-pref", pantryView); }, [pantryView]);
  useEffect(() => { sv("pantry-sort-pref", sortBy);     }, [sortBy]);

  function setPantryView(v) { setPantryViewRaw(v); sv("pantry-view-pref", v); }
  function setSortBy(v)     { setSortByRaw(v);     sv("pantry-sort-pref", v); }

  // ── Toast ────────────────────────────────────────────────────────────────
  // action: optional callback shown as an "Undo" button inside the toast
  function showToast(msg, type = "success", action = null) {
    setToast({ msg, type, action });
    setTimeout(() => setToast(null), action ? 5000 : 3500);
  }
  function dismissToast() { setToast(null); }

  // ── Navigation ───────────────────────────────────────────────────────────
  function goTab(dest) {
    if (tab === "settings" && dest !== "settings") {
      const changed = JSON.stringify(settings) !== savedSettingsRef.current;
      if (changed) {
        withConfirm("confirmLeave", {
          icon:"⚠️", title:"Discard settings changes?",
          message:"You have unsaved changes. Leave without saving?",
          confirmLabel:"Discard", confirmColor:"#e55a42",
        }, () => {
          setSettings(JSON.parse(savedSettingsRef.current));
          setTabRaw(dest); setMode("pantry"); setEditItem(null);
        });
        return;
      }
    }
    if (dest === "settings") setPrevTab(tab);
    setTabRaw(dest); setMode("pantry"); setEditItem(null);
  }

  function setTab(t) { setTabRaw(t); }

  // ── Confirmation system ──────────────────────────────────────────────────
  function withConfirm(settingKey, opts, action) {
    if (settings[settingKey] === false) { action(); return; }
    setPendingConfirm({ ...opts, action });
  }

  // ── Undo ─────────────────────────────────────────────────────────────────
  function pushUndo(label) {
    setUndoStack(prev => [
      { label, snapshot:{ items:[...items], groceryOv:{...groceryOv}, transferOv:{...transferOv} }, at:new Date().toISOString() },
      ...prev.slice(0, 29),
    ]);
  }
  function applyUndo(entry) {
    setItems(entry.snapshot.items);
    setGroceryOv(entry.snapshot.groceryOv);
    setTransferOv(entry.snapshot.transferOv || {});
    setUndoStack(prev => prev.filter(e => e.at !== entry.at));
    showToast("Undone!");
    setShowUndoHistory(false);
  }

  // ── Grocery helpers ──────────────────────────────────────────────────────
  const setGrocNeed = (id, qty) =>
    setGroceryOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), neededQty:Math.max(1,qty) } }));
  const pinGrocery   = id => setGroceryOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), pinned:true, excluded:false } }));
  const unpinGrocery = (id, name="") => {
    withConfirm("confirmRemoveGrocery",
      { icon:"🛒", title:"Remove from grocery list?",
        message: name ? `"${name}" will be removed from the grocery list.` : "This item will be removed.",
        confirmLabel:"Remove", confirmColor:"#e77d00" },
      // Set excluded:true so auto-threshold inclusion is also suppressed.
      () => setGroceryOv(prev => ({ ...prev, [id]: { excluded:true } }))
    );
  };

  // ── Transfer helpers ─────────────────────────────────────────────────────
  const pinTransfer   = id => setTransferOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), pinned:true } }));
  const unpinTransfer = id => setTransferOv(prev => { const n={...prev}; delete n[id]; return n; });

  // ── Shared pantry sync ───────────────────────────────────────────────────
  // Stored in localStorage so it survives page refresh — used to detect own pushes.
  const myLastPushTs = useRef(ld("pantry-my-last-push", 0) || 0);
  const syncRef      = useRef(null);
  const [pushStatus, setPushStatus] = useState("idle"); // idle | pending | pushing

  /** Convert syncInterval + syncIntervalUnit to milliseconds. */
  function intervalMs(s) {
    const n = s.syncInterval ?? 1;
    const u = s.syncIntervalUnit ?? "minutes";
    const multipliers = { seconds:1000, minutes:60000, hours:3600000, days:86400000 };
    return Math.max(800, n * (multipliers[u] ?? 60000));
  }

  /** Record the timestamp we embedded in the last push, persisted across reloads. */
  function recordPush(ts) {
    myLastPushTs.current = ts;
    sv("pantry-my-last-push", ts);
  }

  // Auto-push on items/groceryOv change (only when autoSync is enabled)
  useEffect(() => {
    if (!settings.autoSync || !pantryCode || !sharePw) return;
    setPushStatus("pending");
    clearTimeout(syncRef.current);
    syncRef.current = setTimeout(async () => {
      setPushStatus("pushing");
      const ts = Date.now();
      await pushShared(pantryCode, sharePw, items, groceryOv, transferOv, myName);
      recordPush(ts);
      setPushStatus("idle");
    }, intervalMs(settings));
    return () => clearTimeout(syncRef.current);
  }, [items, groceryOv, transferOv, pantryCode, sharePw, myName, settings.autoSync, settings.syncInterval, settings.syncIntervalUnit]);

  const doSync = useCallback(async () => {
    if (!pantryCode || !sharePw) return;
    setSyncStatus("syncing");
    try {
      // Always pull first — so we never overwrite another device's changes.
      // Pass our last-received timestamp so pullShared can skip decryption
      // when nothing has changed on the remote (JSONBin always sends the full
      // blob; this avoids wasted CPU without an extra API call).
      const lastReceived = ld("pantry-last-received", 0) || 0;
      const r = await pullShared(pantryCode, sharePw, lastReceived);

      if (r) {
        // r is null when remote updatedAt <= lastReceived (nothing new)
        const isOwn = r.updatedAt === myLastPushTs.current;
        if (!isOwn) {
          // Merge at item level — newer updatedAt per item wins.
          // This means two devices editing *different* items never lose data.
          // Two devices editing the *same* item: last push wins (best we can
          // do with a single-document store, but now it's per-item not whole-array).
          setItems(prev => mergeItems(prev, r.items || []));
          setGroceryOv(prev => ({ ...r.groceryOv, ...prev }));
          if (r.transferOv) setTransferOv(prev => ({ ...r.transferOv, ...prev }));
          sv("pantry-last-received", r.updatedAt);
          setLastSyncBy(r.updatedBy || null);
          setLastSyncTime(Date.now());
          if (r.updatedBy) showToast(`Synced from ${r.updatedBy}`, "info");
        }
      }

      // When auto-push is off, also upload our local state —
      // but only if remote had nothing newer (so we don't overwrite fresh data).
      if (!settings.autoSync && !r) {
        const ts = Date.now();
        await pushShared(pantryCode, sharePw, items, groceryOv, transferOv, myName);
        recordPush(ts);
        sv("pantry-last-received", ts);
      }

      setLastSyncTime(Date.now());
      setSyncStatus("ok");
      setTimeout(() => setSyncStatus("idle"), 3000);
    } catch { setSyncStatus("idle"); }
  }, [pantryCode, sharePw, settings.autoSync, items, groceryOv, transferOv, myName]);

  async function createShared() {
    if (createPw.length < 4) { setCreatePwErr("Password must be at least 4 characters."); return; }
    if (createPw !== createPw2) { setCreatePwErr("Passwords don't match."); return; }
    setCreatePwErr("Creating…");
    try {
      const shortCode = genCode();
      const { encryptData } = await import("../utils/crypto");
      const enc = await encryptData({ items, groceryOv, transferOv, updatedAt:Date.now(), updatedBy:myName||"Me" }, createPw + shortCode);
      const binId = await jbCreate({ enc, code:shortCode, updatedAt:Date.now() });
      if (!binId) { setCreatePwErr("Failed to create bin. Check your API key."); return; }
      const fullCode = `${shortCode}:${binId}`;
      setPantryCode(fullCode); sv(K.pantryCode, fullCode);
      setSharePw(createPw);    sv(K.sharePwRaw, createPw);
      setCreatePw(""); setCreatePw2(""); setCreatePwErr("");
    } catch (e) { setCreatePwErr("Error: " + e.message); }
  }

  async function joinShared() {
    if (!joinCode.includes(":")) { setJoinErr("Invalid code — should include ':'"); return; }
    if (!joinPw) { setJoinErr("Enter the pantry password."); return; }
    setJoinErr("Joining…");
    try {
      const r = await pullShared(joinCode, joinPw);
      if (!r) { setJoinErr("Wrong code or password."); return; }
      setPantryCode(joinCode); sv(K.pantryCode, joinCode);
      setSharePw(joinPw);      sv(K.sharePwRaw, joinPw);
      if (r.items)     setItems(r.items);
      if (r.groceryOv)  setGroceryOv(r.groceryOv);
      if (r.transferOv) setTransferOv(r.transferOv);
      setJoinCode(""); setJoinPw(""); setJoinErr("");
    } catch (e) { setJoinErr("Error: " + e.message); }
  }

  function leaveShared() {
    withConfirm("confirmLeave",
      { icon:"🚪", title:"Leave shared pantry?",
        message:"You'll keep your local items, but won't sync with others anymore.",
        confirmLabel:"Leave", confirmColor:"#e55a42" },
      () => {
        setPantryCode(null); sv(K.pantryCode, null);
        setSharePw("");      sv(K.sharePwRaw, "");
      }
    );
  }

  // ── Save settings ────────────────────────────────────────────────────────
  function saveSettings() {
    savedSettingsRef.current = JSON.stringify(settings);
    sv(K.settings, settings);
    setShowSettingsSaved(true);
    setTimeout(() => { setShowSettingsSaved(false); goTab(prevTab); }, 1200);
  }

  // ── Derived data ─────────────────────────────────────────────────────────
  // Exclude tombstones (deletedAt set) from all derived views — they exist
  // only so other devices learn about the deletion on next sync.
  const allItems = items
    .filter(i => !i.deletedAt)
    .map(i => ({ ...i, totalQty:(i.kitchenQty||0)+(i.storageQty||0) }));

  const expiringSoon = allItems.filter(i => {
    const d = Math.ceil((new Date(i.expiry) - new Date()) / 86400000);
    return i.expiry && d >= 0 && d <= (i.expiryWarnDays ?? settings.expiryWarnDays);
  });
  const expired = allItems.filter(i => {
    const d = Math.ceil((new Date(i.expiry) - new Date()) / 86400000);
    return i.expiry && d < 0;
  });

  const transferList = allItems.filter(i => {
    if (transferOv[i.id]?.pinned) return true;
    const kt = i.kitchenThreshold ?? settings.kitchenThreshold;
    // threshold 0 means "never show in transfer list"
    return kt > 0 && i.kitchenQty <= kt && i.storageQty > 0;
  });
  const groceryList = allItems.filter(i => {
    const ov = groceryOv[i.id];
    if (ov?.excluded) return false;
    if (ov?.pinned) return true;
    const tt = i.totalThreshold ?? settings.totalThreshold;
    // threshold 0 means "never auto-add to grocery list"
    return tt > 0 && i.totalQty <= tt;
  }).sort((a, b) => a.totalQty - b.totalQty);

  const qrJoinUrl = pantryCode
    ? `${window.location.origin}${window.location.pathname}?code=${pantryCode}&pw=${encodeURIComponent(sharePw)}`
    : null;

  return (
    <PantryContext.Provider value={{
      // State
      deviceId,
      items, setItems, settings, setSettings, groceryOv, setGroceryOv, transferOv, setTransferOv,
      pantryCode, sharePw, myName, setMyName, syncStatus, lastSyncTime, lastSyncBy,
      tab, setTab, prevTab, mode, setMode,
      editItem, setEditItem,
      pantryView, setPantryView, sortBy, setSortBy,
      filterCat, setFilterCat, search, setSearch,
      toast, pendingConfirm, setPendingConfirm,
      historyItem, setHistoryItem,
      undoStack, setUndoStack, showUndoHistory, setShowUndoHistory,
      showSettingsSaved, setShowSettingsSaved, showGroceryExport, setShowGroceryExport,
      showImportModal, setShowImportModal,
      showAddSheet, setShowAddSheet,
      showQR, setShowQR,
      scanning, setScanning, scanStatus, setScanStatus,
      scanLocation, setScanLocation, scanCard, setScanCard,
      pendingRm, setPendingRm, showRmReview, setShowRmReview,
      createPw, setCreatePw, createPw2, setCreatePw2, createPwErr, setCreatePwErr,
      joinCode, setJoinCode, joinPw, setJoinPw, joinErr, setJoinErr,
      savedSettingsRef,
      // Derived
      allItems, expiringSoon, expired, transferList, groceryList, qrJoinUrl,
      // Actions
      goTab, showToast, dismissToast, withConfirm,
      pushUndo, applyUndo,
      setGrocNeed, pinGrocery, unpinGrocery,
      pinTransfer, unpinTransfer,
      pushStatus,
      doSync, createShared, joinShared, leaveShared,
      saveSettings,
      onLock,
    }}>
      {children}
    </PantryContext.Provider>
  );
}
