            <div style={S.empty}><div style={{fontSize:52}}>🛒</div><div style={{fontFamily:"Fraunces,serif",fontSize:20,marginTop:10}}>All stocked up!</div><p style={{color:t.textDim,marginTop:8,fontSize:13}}>Nothing to buy right now.</p></div>
