// features/transfer/TransferRow.js
import { useState } from "react";
import { SS, Mo } from "../../utils/theme";
import { HoldButton } from "../../components/HoldButton";
import { KITCHEN_ICON, STORAGE_ICON } from "../../constants";

export function TransferRow({ item, defaultQty = 1, unit, onMove }) {
  const def = Math.max(1, defaultQty);
  const [qty, setQty] = useState(def);
  return (
    <div style={{display:"flex",alignItems:"center",gap:8,padding:"8px 10px",
      background:"var(--blue-bg)",borderRadius:8,flexWrap:"wrap"}}>
      <HoldButton onPress={()=>setQty(q=>Math.max(1,q-1))} style={{...Mo.qBtn,width:26,height:26}}>−</HoldButton>
      <span style={{fontSize:14,fontWeight:700,minWidth:24,textAlign:"center",color:"var(--blue)"}}>{qty}</span>
      <HoldButton onPress={()=>setQty(q=>Math.min(Math.max(item.kitchenQty,item.storageQty),q+1))} style={{...Mo.qBtn,width:26,height:26}}>+</HoldButton>
      <span style={{fontSize:11,color:"var(--text-dim)"}}>{unit}</span>
      <button
        onClick={()=>onMove(qty,"storage")}
        disabled={item.storageQty<qty}
        style={{...SS.primaryBtn,marginLeft:"auto",padding:"6px 12px",fontSize:12,
          opacity:item.storageQty>=qty?1:0.35}}>
        {STORAGE_ICON}→{KITCHEN_ICON}
      </button>
      <button
        onClick={()=>{onMove(qty,"kitchen");setQty(def);}}
        disabled={item.kitchenQty<qty}
        style={{...SS.secondaryBtn,padding:"6px 12px",fontSize:12,
          opacity:item.kitchenQty>=qty?1:0.35}}>
        {KITCHEN_ICON}→{STORAGE_ICON}
      </button>
    </div>
  );
}

export function TransferInline({ item, defaultQty = 1, onMove, onQtyChange, ki=KITCHEN_ICON, si=STORAGE_ICON }) {
  const def = Math.max(1, defaultQty);
  const [qty, setQty] = useState(def);

  function changeQty(newQty) {
    setQty(newQty);
    onQtyChange?.(newQty);
  }

  return (
    <div style={{marginBottom:12,padding:12,background:"var(--blue-bg)",
      border:"1px solid var(--blue-bg)",borderRadius:10}}>
      <div style={{fontSize:12,fontWeight:600,color:"var(--blue)",marginBottom:10}}>
        🔄 Transfer stock
      </div>
      <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:8}}>
        <span style={{fontSize:12,color:"var(--text-mid)",flexShrink:0}}>Qty:</span>
        <HoldButton onPress={()=>changeQty(Math.max(1,qty-1))} style={{...Mo.qBtn,width:28,height:28}}>−</HoldButton>
        <span style={{fontSize:15,fontWeight:700,color:"var(--text)",minWidth:26,textAlign:"center"}}>{qty}</span>
        <HoldButton onPress={()=>changeQty(Math.min(Math.max(item.kitchenQty,item.storageQty),qty+1))} style={{...Mo.qBtn,width:28,height:28}}>+</HoldButton>
      </div>
      <div style={{display:"flex",gap:8}}>
        <button
          onClick={()=>onMove(item.id,"storage",qty,item.name)}
          disabled={item.storageQty<qty}
          style={{...SS.primaryBtn,flex:1,fontSize:12,padding:"7px 8px",
            opacity:item.storageQty>=qty?1:0.35}}>
          {si} → {ki} To Kitchen
        </button>
        <button
          onClick={()=>{onMove(item.id,"kitchen",qty,item.name);setQty(def);}}
          disabled={item.kitchenQty<qty}
          style={{...SS.secondaryBtn,flex:1,fontSize:12,padding:"7px 8px",
            opacity:item.kitchenQty>=qty?1:0.35}}>
          {ki} → {si} To Storage
        </button>
      </div>
    </div>
  );
}
